\documentclass{article}
\usepackage[T1]{fontenc}
\usepackage[utf8]{inputenc}
\usepackage[spanish]{babel}
\usepackage{amssymb}
\usepackage{amsmath}
\usepackage{amsthm}

\title{Cuaderno matemático}
\author{Estudiante}
\date{\today}

\begin{document}
\maketitle

\begin{proof}
Para $a=2m$ y $b=2n$:
\begin{align*}a+b&=2m+2n\\&=2(m+n)\end{align*}
Luego, $a+b$ es par.
\end{proof}
